def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    colored_rows = [r for r, row in enumerate(grid) if any(row)]
    if not colored_rows:
        return [row[:] for row in grid]
    bottom = max(colored_rows)
    out = [[0] * w for _ in range(h)]
    for r, row in enumerate(grid):
        shift = r - bottom
        for c, value in enumerate(row):
            if value:
                nc = c + shift
                if 0 <= nc < w:
                    out[r][nc] = value
    return out

